import{z as s,x as o,o as l,c as p,q as t,j as i,D as a,d as B,s as n,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"液冷与热设计","description":"","frontmatter":{"title":"液冷与热设计","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/liquid-cooling-thermal.md","filePath":"llm/liquid-cooling-thermal.md","lastUpdated":1791413859000}'),d={name:"llm/liquid-cooling-thermal.md"};function D(C,E,m,h,u,F){const r=o("Mermaid");return l(),p("div",null,[E[2]||(E[2]=t('<h1 id="液冷与热设计" tabindex="-1">液冷与热设计 <a class="header-anchor" href="#液冷与热设计" aria-label="Permalink to &quot;液冷与热设计&quot;">​</a></h1><div class="epigraph"><p>风冷的极限是机柜能带走的热；液冷换的是传热介质，不是把热力学取消。水侧一停，加速器域比风扇停得更彻底。</p><footer>—— 对照高密度 GPU 机柜的冷板 / CDU 公开形态；功率密度见上一课</footer></div><p><a href="/llm/rack-power-density">上一课</a> 把卡数上限写成电。本课写热：同样的千瓦必须离开芯片。缺口是液冷如何改变故障模式与维护，而不是科普「水比空气热容大」。超节点产品形态公开为液冷托盘；<a href="/llm/nvlink">NVLink</a> 域、供电域、冷却域往往重叠成<strong>同一个爆炸半径</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>风冷在 15 kW 以上机柜开始吃力：风量、噪声、热通道温度、以及 GPU 因进风不均而降频。冷板液冷把热从封装接到二次水，机柜可以堆到公开超节点那种密度。代价是：泄漏、水质、冷凝、CDU（分配单元）成为单点；维护要从「热插拔风扇」变成「关水、排液、换冷板」。问题是把冷却当成与 NCCL 同级的可用性输入：一次 CDU 故障可以让整柜 GPU 过热关机，step 丢失，等价于一次超大规模集体超时。</p><p><span class="marginnote">数字实例：同样一升流体升温 10 度，水能带走约 42 千焦热量，空气只有约 12 焦——差三千多倍。这就是「风冷 15 千瓦就吃力、冷板液冷机柜能上几十上百千瓦」的物理来源：不是水更「凉」，而是单位流量能搬走的热多得多。</span></p><p>冷热不均同样有害：同一域里一张卡降频，All-Reduce 等最慢 rank，整步变慢。热设计失败表现为通信墙一样的症状，根因在进水温度与流量，不在算法。</p><p><span class="marginnote">一次水 / 二次水、CDU、歧管、冷板是常见分层。本课不画未公开的管路直径与流量公式。规划用厂商允许的进水温度范围与机房能否提供该水为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把冷却域画进拓扑图：哪些 GPU 共享 CDU、哪些共享歧管。故障演练按域下电，而不是按单卡。监控进水温度、回水温度、流量、泄漏传感器，与 GPU 热点、时钟、Xid 对齐时间轴——热事件往往先于 CUDA 错误。</p><p>作业调度避免在冷却余量不足时打满 Tensor Core 训练；降功率模式是保护，应告警为设施事件。液冷不能当「无限密度」：机房排热（冷却塔、外水）仍是屋顶线。PUE 变好只说明风扇电少了，厂级排热仍在。</p><p><span class="marginnote">PUE（电源使用效率）= 机房总耗电 ÷ IT 设备耗电，1.5 就是「每给 GPU 一度电，设施侧再烧半度」。冷板液冷把风扇电省掉、PUE 逼近 1.1，但热本身没有消失——只是从「机房风扇搬」变成「冷却塔和外水搬」，账单只是换了地方。</span></p>',12)),(l(),i(A,null,{default:a(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIE%5B%22GPU%20%E5%B0%81%E8%A3%85%22%5D%20--%3E%20PLATE%5B%22%E5%86%B7%E6%9D%BF%22%5D%0A%20%20PLATE%20--%3E%20CDU%5B%22CDU%20%2F%20%E4%BA%8C%E6%AC%A1%E6%B0%B4%22%5D%0A%20%20CDU%20--%3E%20FAC%5B%22%E6%9C%BA%E6%88%BF%E6%8E%92%E7%83%AD%22%5D%0A%20%20CDU%20--%3E%20FAIL%5B%22%E5%86%B7%E5%8D%B4%E5%9F%9F%E6%95%85%E9%9A%9C%22%5D%0A%20%20FAIL%20--%3E%20RACK%5B%22%E6%95%B4%E6%9F%9C%E9%99%8D%E9%A2%91%E6%88%96%E5%85%B3%E6%9C%BA%22%5D%0A%20%20RACK%20--%3E%20STEP%5B%22%E9%9B%86%E4%BD%93%E7%AD%89%E5%BE%85%E6%9C%80%E6%85%A2%E5%8D%A1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"风冷机柜与液冷机柜混部时，不要按同一套进风假设做容量。也不要把液冷 GPU 插进只有风冷的机架——这不是软件开关。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"芯片功耗变成热流，冷板靠接触与流量带走。流量不足或气泡导致局部热阻上升，热点降频。同步训练让整柜同时进入高功耗，水侧看到的是方波；CDU 控制环若按缓慢的数据中心负荷设计，会在方波前沿过冲。这与网络拥塞控制环慢于集体脉冲是同一类「控制环跟不上训练时钟」的问题。",-1)),(l(),i(A,null,{default:a(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E8%AE%AD%E7%BB%83%20step%20%E5%BC%80%E5%A7%8B%EF%BC%9A%E5%85%A8%E6%9F%9C%E5%90%8C%E6%AD%A5%E6%8B%89%E6%BB%A1%E5%8A%9F%E8%80%97%22%5D%20--%3E%20SQ%5B%22%E6%B0%B4%E4%BE%A7%E8%B4%9F%E8%8D%B7%E5%91%88%E6%96%B9%E6%B3%A2%EF%BC%8C%E5%89%8D%E6%B2%BF%E6%9C%80%E9%99%A1%22%5D%0A%20%20SQ%20--%3E%20CTL%5B%22CDU%20%E6%8E%A7%E5%88%B6%E7%8E%AF%E6%8C%89%E7%BC%93%E6%85%A2%E8%B4%9F%E8%8D%B7%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20CTL%20--%3E%20OS%5B%22%E5%89%8D%E6%B2%BF%E8%BF%87%E5%86%B2%EF%BC%9A%E8%BF%9B%E6%B0%B4%E6%B8%A9%E5%BA%A6%E7%9F%AD%E6%97%B6%E8%B5%B0%E9%AB%98%22%5D%0A%20%20OS%20--%3E%20HOT%5B%22%E5%B1%80%E9%83%A8%E7%83%AD%E9%98%BB%E4%B8%8A%E5%8D%87%EF%BC%8C%E7%83%AD%E7%82%B9%E5%8D%A1%E5%85%88%E9%99%8D%E9%A2%91%22%5D%0A%20%20HOT%20--%3E%20SLOW%5B%22All-Reduce%20%E7%AD%89%E6%9C%80%E6%85%A2%20rank%EF%BC%8C%E6%95%B4%E6%AD%A5%E5%8F%98%E6%85%A2%22%5D%0A%20%20TR%20--%3E%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9A%E6%B0%B4%E6%B8%A9%20%2F%20%E6%97%B6%E9%92%9F%20%2F%20Xid%20%E5%AF%B9%E9%BD%90%E6%97%B6%E9%97%B4%E8%BD%B4%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">直觉类比：同步训练像一支并排跑的队伍，水冷系统是按「散步节奏」调的空调——每次发令枪一响（step 开始），全柜功耗瞬间打满，空调来不及反应，队伍里最怕热的那个（热点卡）先减速，而全队必须等他。降的不是平均性能，是最差那一卡的短板。</span></p><p>泄漏检测必须比电气保护更快：水进电是安全事件。因此液冷域的维护窗口更长，调度要预留，不能按风冷的热插拔 SLA 写训练作业的恢复时间。</p><p><span class="marginnote">浸没式冷却是另一条产品线，故障与维护模型又不同。没有部署就不要把浸没的营销 PUE 写进当前风冷/冷板机房的规划。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用液冷当节能的唯一理由——主因是密度。不要忽略凝露：进水过冷、机房露点高，冷板会结露。不要把未公开的「某代 120 kW 机柜」数字写进课；用你合同里的规格。下一课 GPU 故障模式包含热相关的 Xid 与静默错误，冷却是诱因之一。</p><p><span class="marginnote">常见误区：初学者容易以为液冷是「水直接浇在芯片上」。冷板方案里，水从头到尾不接触芯片——冷板是一块带流道的金属板贴在芯片封装上，热经金属传给板内水流。真正泡在冷却液里的是另一条「浸没式」路线，故障模型完全不同，两者不要混着讨论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>液冷支撑功率密度，把故障域收成 CDU / 机柜级。</li><li>单卡降频通过集体同步变成整步变慢。</li><li>监控水侧与 GPU 时钟对齐；控制环必须扛住训练方波。</li><li>维护与 SLA 不能按风冷热插拔来写。</li><li>出处：公开超节点液冷形态；设施进水温度与泄漏保护实践。</li></ul>',8))])}const T=s(d,[["render",D]]);export{c as __pageData,T as default};
